-- =====================================================
-- Library API: database schema (provider-neutral)
-- Types are generic: EF Core maps them to each database.
-- Tables are created through EF Core migrations.
-- =====================================================

-- Columns inherited from BaseEntity (all tables except audit_logs)
--   id          uuid        PK (Guid v7, generated by the application)
--   created_at  timestamp   NOT NULL (UTC)
--   updated_at  timestamp   NOT NULL (UTC)
--   created_by  uuid        NULL FK users   (added with auditing)
--   updated_by  uuid        NULL FK users   (added with auditing)

users                       -- library staff who log in
  full_name        varchar(150)  NOT NULL
  email            varchar(254)  NOT NULL UNIQUE
  password_hash    varchar(100)  NOT NULL   -- bcrypt
  role             varchar(20)   NOT NULL   -- Employee | Manager
  is_active        boolean       NOT NULL DEFAULT true

members                     -- registered readers
  card_number      int           NOT NULL UNIQUE   -- generated by the application
  full_name        varchar(150)  NOT NULL
  email            varchar(254)  NULL UNIQUE
  phone_number     varchar(20)   NULL
  cpf              varchar(11)   NULL UNIQUE       -- digits only, optional
  status           varchar(20)   NOT NULL          -- Active | Suspended | Inactive

books                       -- catalog entry, with copy count
  title            varchar(200)  NOT NULL
  author_name      varchar(200)  NOT NULL
  isbn             varchar(13)   NULL UNIQUE
  publisher        varchar(150)  NULL
  description      varchar(2000) NULL
  category         varchar(100)  NOT NULL
  total_copies     int           NOT NULL CHECK (total_copies >= 0)
  is_active        boolean       NOT NULL DEFAULT true   -- soft delete
  version          int           NOT NULL                -- concurrency token

loans
  member_id            uuid          NOT NULL FK members
  book_id              uuid          NOT NULL FK books
  borrowed_at          timestamp     NOT NULL
  due_at               timestamp     NOT NULL
  returned_at          timestamp     NULL
  status               varchar(20)   NOT NULL          -- Active | Returned | Cancelled
  cancellation_reason  varchar(300)  NULL
  fine_amount          decimal(10,2) NULL              -- snapshot at return
  INDEX (book_id, status)
  INDEX (member_id, status)

audit_logs                  -- append-only, does not inherit BaseEntity
  id             uuid          PK
  user_id        uuid          NOT NULL FK users
  action         varchar(50)   NOT NULL
  entity_name    varchar(100)  NOT NULL
  entity_id      uuid          NOT NULL
  occurred_at    timestamp     NOT NULL (UTC)
  old_values     text          NULL    -- serialized JSON
  new_values     text          NULL    -- serialized JSON

-- Relationships (all FKs with ON DELETE RESTRICT, no cascade)
--   members 1:N loans
--   books   1:N loans
--   users   1:N audit_logs